// android/ is regenerated by `expo prebuild` (it's gitignored), so it always ships
// with a template that signs release builds using the debug keystore. This patches
// android/app/build.gradle to sign release builds with the real release keystore
// (../keystore.properties + ../release.keystore, both outside android/ so they
// survive prebuild) instead. Safe to run repeatedly — skips if already patched.
const fs = require("node:fs");
const path = require("node:path");

const BUILD_GRADLE_PATH = path.join(__dirname, "..", "android", "app", "build.gradle");

const LOADER_SNIPPET = `def projectRoot = rootDir.getAbsoluteFile().getParentFile().getAbsolutePath()

def keystorePropertiesFile = new File(projectRoot, "keystore.properties")
def keystoreProperties = new Properties()
def hasReleaseKeystore = keystorePropertiesFile.exists()
if (hasReleaseKeystore) {
    keystoreProperties.load(new FileInputStream(keystorePropertiesFile))
}`;

const OLD_LOADER_LINE = 'def projectRoot = rootDir.getAbsoluteFile().getParentFile().getAbsolutePath()';

const OLD_SIGNING_CONFIGS = `signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
    }`;

const NEW_SIGNING_CONFIGS = `signingConfigs {
        debug {
            storeFile file('debug.keystore')
            storePassword 'android'
            keyAlias 'androiddebugkey'
            keyPassword 'android'
        }
        release {
            if (hasReleaseKeystore) {
                storeFile new File(projectRoot, keystoreProperties['storeFile'])
                storePassword keystoreProperties['storePassword']
                keyAlias keystoreProperties['keyAlias']
                keyPassword keystoreProperties['keyPassword']
            }
        }
    }`;

module.exports = function ensureReleaseSigning() {
  if (!fs.existsSync(BUILD_GRADLE_PATH)) {
    return;
  }

  let contents = fs.readFileSync(BUILD_GRADLE_PATH, "utf8");
  if (contents.includes("hasReleaseKeystore")) {
    return;
  }

  if (!contents.includes(OLD_LOADER_LINE) || !contents.includes(OLD_SIGNING_CONFIGS)) {
    console.warn(
      "[ensure-release-signing] android/app/build.gradle no coincide con la plantilla esperada; " +
        "revisa el firmado de release manualmente.",
    );
    return;
  }

  contents = contents.replace(OLD_LOADER_LINE, LOADER_SNIPPET);
  contents = contents.replace(OLD_SIGNING_CONFIGS, NEW_SIGNING_CONFIGS);
  contents = contents.replace(
    /release \{\n(\s*)\/\/ Caution![^\n]*\n(\s*)\/\/ see[^\n]*\n(\s*)signingConfig signingConfigs\.debug/,
    "release {\n$1// Firma con el keystore real si existe (keystore.properties en la raíz del repo);\n" +
      "$2// cae al keystore de debug solo si alguien clona el repo sin él.\n" +
      "$3signingConfig hasReleaseKeystore ? signingConfigs.release : signingConfigs.debug",
  );

  fs.writeFileSync(BUILD_GRADLE_PATH, contents);
  console.log("[ensure-release-signing] android/app/build.gradle parcheado para firmar con el keystore de release.");
};

if (require.main === module) {
  module.exports();
}
